203	/** What one published draft resolves to before anything is pushed. */
204	export interface DraftFile {
205	  /** Absolute path of the local original, checked for readability. */
206	  source: string;
207	  /** Path on the branch, checked for the shape git accepts. */
208	  target: string;
209	}
