211	/**
212	 * Resolve the drafts a caller named, or say which one is unusable.
213	 *
214	 * Every refusal below is a hole that would otherwise be found after a push: a path
215	 * resolved against the wrong directory, a target that git will not accept, and two
216	 * drafts writing the same path — which would publish one file and report two.
217	 *
218	 * A relative `path` is resolved against `process.cwd()`, which is the work tree for
219	 * the same reason it is in `mcp/files.ts`: atoma starts every server as a child of the
220	 * run and inherits the directory the run was started in, which the runner starts at
221	 * the workspace root. A server started anywhere else resolves relative paths there,
222	 * and the refusal below says which directory that was rather than leaving the caller
223	 * to guess.
224	 */
225	export function resolveDraftFiles(files: { path: string; target: string }[]): DraftFile[] {
226	  const base = resolve(process.cwd());
227	  // The work tree and /tmp — the pinned interface: a draft is either a file in the
228	  // checkout or an absolute path under /tmp, which is where a conversion step puts its
229	  // output. `/tmp/atomaton-workspace` is the one subdirectory of it that survives a run.
230	  const roots = [base, TMP_ROOT];
231	  const seen = new Set<string>();
232	  const out: DraftFile[] = [];
233	
234	  for (const file of files) {
235	    const source = isAbsolute(file.path) ? resolve(file.path) : resolve(base, file.path);
236	    if (!roots.some((root) => source === root || source.startsWith(root + sep))) {
237	      throw new Error(
238	        `'${file.path}' resolves to '${source}', which is outside the places a draft may be read from ` +
239	          `(${roots.join(", ")}). Pass an absolute path, or one relative to ${base}.`,
240	      );
241	    }
242	    let size: number;
243	    try {
244	      const stats = statSync(source);
245	      if (!stats.isFile()) {
246	        throw new Error(`'${file.path}' is not a file (${source}); a draft is one file per target.`);
247	      }
248	      size = stats.size;
249	    } catch (error) {
250	      if (error instanceof Error && error.message.includes("is not a file")) throw error;
251	      throw new Error(`could not read '${file.path}': no such file at ${source}`);
252	    }
253	    if (size > MAX_READ_BYTES) {
254	      throw new Error(`${source} is ${size} bytes, past the ${MAX_READ_BYTES}-byte ceiling this tool publishes.`);
255	    }
256	    const target = normalizeTarget(file.target);
257	    if (seen.has(target)) {
258	      throw new Error(`two drafts target '${target}'; one would overwrite the other and the result would report both.`);
259	    }
260	    seen.add(target);
261	    out.push({ source, target });
262	  }
263	  return out;
264	}
