270	 * path is a warning on stderr and exit code 0 in one case (`Ignoring path /etc/x`):
271	 * the push would then succeed with the file simply absent, and the tool would report
272	 * a URL for a document that is not on the branch.
273	 */
274	function normalizeTarget(target: string): string {
275	  const trimmed = target.replace(/^\/+/, "");
276	  if (!trimmed) throw new Error("a draft's target cannot be empty.");
277	  if (isAbsolute(target) || target.startsWith("/")) {
278	    throw new Error(`target '${target}' must be relative to the branch, not absolute.`);
279	  }
280	  if (trimmed.startsWith("-")) {
281	    throw new Error(`target '${target}' starts with '-', which the index listing would read as an argument.`);
282	  }
283	  if (trimmed.includes("\\")) {
284	    throw new Error(`target '${target}' contains a backslash; branch paths are separated by '/'.`);
285	  }
286	  if (/[\t\n\r\0]/.test(trimmed)) {
287	    throw new Error(`target '${target}' contains a tab, newline or NUL, which the index listing cannot express.`);
288	  }
289	  const parts = trimmed.split("/");
290	  if (parts.some((part) => part === "" || part === "." || part === "..")) {
291	    throw new Error(`target '${target}' has an empty, '.' or '..' path segment, which git will not accept.`);
292	  }
293	  if (parts.some((part) => part.toLowerCase() === ".git")) {
294	    throw new Error(`target '${target}' is under .git, which git refuses to write a blob into.`);
295	  }
296	  return trimmed;
297	}
